import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure target_state has the right structure
    if target_state.empty:
        target_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    # Ensure cdc_events has the right structure
    if cdc_events.empty:
        cdc_events = pd.DataFrame(columns=["seq", "order_id", "op", "status", "amount", "event_ts"])

    # 1. Remove duplicate events (keep first occurrence of each seq)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first").reset_index(drop=True)

    # 2. Build a dict of target_state for fast lookup
    target_dict = {}
    if not target_state.empty:
        for _, row in target_state.iterrows():
            target_dict[row["order_id"]] = {
                "status": row["status"],
                "amount": row["amount"],
                "last_seq": row["last_seq"]
            }

    # Track which orders had rows at some point (for tombstones)
    orders_with_history = set(target_dict.keys())

    # 3. Apply events in seq order, per order
    for _, event in cdc_events.iterrows():
        seq = event["seq"]
        order_id = event["order_id"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        # Replay guard: skip if order exists and seq <= last_seq
        if order_id in target_dict:
            if seq <= target_dict[order_id]["last_seq"]:
                continue

        # Mark this order as having had a row at some point
        orders_with_history.add(order_id)

        # Apply the operation
        if op in ("I", "U"):
            if order_id not in target_dict:
                # Create new row
                target_dict[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }
            else:
                # Update existing row
                target_dict[order_id]["status"] = status
                # For 'U' with NULL amount, keep existing amount; otherwise use new amount
                if op == "U" and pd.isna(amount):
                    # Keep existing amount
                    pass
                else:
                    target_dict[order_id]["amount"] = amount
                target_dict[order_id]["last_seq"] = seq
        elif op == "D":
            # Delete the row
            if order_id in target_dict:
                del target_dict[order_id]

    # 4. Build new_state from target_dict
    new_state_rows = []
    for order_id, data in target_dict.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": data["status"],
            "amount": data["amount"],
            "last_seq": data["last_seq"]
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "object",
            "amount": "float64",
            "last_seq": "int64"
        })
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "object",
            "amount": "float64",
            "last_seq": "int64"
        })

    # 5. Build tombstones: orders with history whose last event was a 'D'
    tombstone_rows = []

    # Track the last event per order (in seq order)
    last_event_per_order = {}
    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]
        op = event["op"]

        # Only consider events that passed the replay guard
        if order_id in target_dict or order_id in orders_with_history:
            # Check replay guard again for this logic
            if order_id in target_dict:
                # Current state exists
                if seq <= target_dict[order_id]["last_seq"]:
                    continue
            elif order_id in last_event_per_order:
                # Order was deleted, check against last applied event
                if seq <= last_event_per_order[order_id]["seq"]:
                    continue

        last_event_per_order[order_id] = {"seq": seq, "op": op}

    # Now check which orders' last event was a 'D'
    for order_id, event_info in last_event_per_order.items():
        if event_info["op"] == "D" and order_id in orders_with_history:
            tombstone_rows.append({
                "order_id": order_id,
                "deleted_seq": event_info["seq"]
            })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
